def solution():
    # Define variables name and value
    december_quantities = [120, 50]
    november_prices = [0.90, 0.60]
    december_prices = [1.00, 0.80]

    # Calculate the Paasche price index using December quantities
    december_basket_cost = sum(
        quantity * price
        for quantity, price in zip(december_quantities, december_prices)
    )
    base_price_basket_cost = sum(
        quantity * price
        for quantity, price in zip(december_quantities, november_prices)
    )
    paasche_index = (december_basket_cost / base_price_basket_cost) * 100

    # return answer to three decimal places
    return round(paasche_index, 3)
